#!/usr/bin/env python3
"""Decode PostgreSQL JSONB binary format to recover deleted rules."""

import struct
import json

# PostgreSQL JSONB binary format (JsEntry layout):
# Bit 31: JENTRY_HAS_OFF (end-offset if set, length if clear)
# Bits 30-28: JENTRY_TYPEMASK (type)
# Bits 27-0: JENTRY_OFFLENFLD (offset or length)
JENTRY_HAS_OFF   = 0x80000000
JENTRY_TYPEMASK  = 0x70000000
JENTRY_OFFLENFLD = 0x0FFFFFFF

# Type codes (bits 30-28)
JENTRY_ISSTRING   = 0x00000000
JENTRY_ISNUMERIC  = 0x10000000
JENTRY_ISFALSEVAL = 0x20000000
JENTRY_ISTRUEVAL  = 0x30000000
JENTRY_ISNULL     = 0x40000000
JENTRY_ISCONTAINER= 0x50000000

# JsonbContainer header flags (bits 31-29)
JB_FSCALAR = 0x80000000
JB_FARRAY  = 0x40000000
JB_FOBJECT = 0x20000000
JB_CMASK   = 0x1FFFFFFF  # count


def strip_varlena(data: bytes) -> bytes:
    """Strip the PostgreSQL varlena header from bytea."""
    if not data:
        return data
    first = data[0]
    if first & 1:
        # 1-byte header: data starts at offset 1
        return data[1:]
    else:
        # 4-byte header: data starts at offset 4
        return data[4:]


def decode_numeric(data: bytes, start: int, length: int):
    """Decode PostgreSQL numeric binary format."""
    if length < 8:
        return 0
    ndigits, weight, sign, dscale = struct.unpack_from('>HHHH', data, start)
    digits = []
    for i in range(ndigits):
        if start + 8 + i*2 + 2 > start + length:
            break
        d, = struct.unpack_from('>H', data, start + 8 + i*2)
        digits.append(d)

    if sign == 0xC000:
        return None  # NaN

    # Reconstruct numeric
    value = 0
    for d in digits:
        value = value * 10000 + d

    if weight >= 0:
        value = value  # integer part

    # Adjust for decimal scale
    # This is a simplified version - might not handle all cases
    int_digits = (weight + 1) if weight >= 0 else 0
    if int_digits > 0 and ndigits > int_digits:
        # Has fractional part
        frac_part = 0
        for i, d in enumerate(digits[int_digits:]):
            frac_part += d / (10000 ** (i + 1))
        int_part = sum(d * (10000 ** (int_digits - 1 - i)) for i, d in enumerate(digits[:int_digits]))
        value = float(int_part) + frac_part
        if dscale == 0:
            value = int(value)
    else:
        value = sum(d * (10000 ** (weight - i)) for i, d in enumerate(digits))
        if dscale == 0:
            value = int(value)

    if sign == 0x4000:
        value = -value

    return value


def parse_jsonb_container(data: bytes, offset: int = 0):
    """Parse a JsonbContainer starting at offset."""
    if offset + 4 > len(data):
        return None

    header = struct.unpack_from('<I', data, offset)[0]
    is_scalar = bool(header & JB_FSCALAR)
    is_array  = bool(header & JB_FARRAY)
    is_object = bool(header & JB_FOBJECT)
    count = header & JB_CMASK

    offset += 4  # skip container header

    # Read JsEntry array
    if is_object:
        n_entries = count * 2  # keys + values
    else:
        n_entries = count

    entries = []
    for _ in range(n_entries):
        if offset + 4 > len(data):
            break
        entry = struct.unpack_from('<I', data, offset)[0]
        entries.append(entry)
        offset += 4

    # Data section starts here
    data_start = offset

    def get_value(entry, prev_end):
        etype = entry & JENTRY_TYPEMASK
        has_off = bool(entry & JENTRY_HAS_OFF)
        offlenfld = entry & JENTRY_OFFLENFLD

        if has_off:
            end = offlenfld
            start = prev_end
        else:
            start = prev_end
            end = prev_end + offlenfld

        length = end - start
        abs_start = data_start + start

        if etype == JENTRY_ISSTRING:
            return data[abs_start:abs_start + length].decode('utf-8', errors='replace'), end
        elif etype == JENTRY_ISNUMERIC:
            val = decode_numeric(data, abs_start, length)
            return val, end
        elif etype == JENTRY_ISFALSEVAL:
            return False, end
        elif etype == JENTRY_ISTRUEVAL:
            return True, end
        elif etype == JENTRY_ISNULL:
            return None, end
        elif etype == JENTRY_ISCONTAINER:
            # Nested container
            nested = parse_jsonb_container(data, abs_start)
            return nested, end
        else:
            # Unknown type - try as string
            return f"<type={hex(etype)} len={length}>", end

    if is_scalar:
        if entries:
            val, _ = get_value(entries[0], 0)
            return val
        return None
    elif is_array:
        result = []
        prev_end = 0
        for entry in entries:
            val, prev_end = get_value(entry, prev_end)
            result.append(val)
        return result
    elif is_object:
        keys = []
        vals = []
        prev_key_end = 0
        for entry in entries[:count]:
            key, prev_key_end = get_value(entry, prev_key_end)
            keys.append(key)

        prev_val_end = prev_key_end
        for entry in entries[count:]:
            val, prev_val_end = get_value(entry, prev_val_end)
            vals.append(val)

        return dict(zip(keys, vals))

    return None


def decode_jsonb(hex_str: str):
    """Decode a PostgreSQL JSONB value from hex string."""
    data = bytes.fromhex(hex_str)
    payload = strip_varlena(data)
    return parse_jsonb_container(payload)


