def main():
    results = {}
    for rule_id, rule in rules_hex.items():
        decoded = {"name": rule["name"], "description": rule.get("description", ""),
                   "schedule_type": rule["schedule_type"]}
        for field in ["conditions", "actions", "scope", "safety"]:
            try:
                decoded[field] = decode_jsonb(rule[field])
            except Exception as e:
                decoded[field] = f"<decode error: {e}>"
        results[rule_id] = decoded

    print(json.dumps(results, indent=2, ensure_ascii=False))


if __name__ == "__main__":
    main()
